AUTHOR CONTEXT (the change author's own description):
play button: cd into the workspace before running the command

WHERE THESE LIVE (resolved from the repository before this review started — treat as already-run searches; do not re-run them):
- POSIX: frontend/dist/app.js:11
- select: frontend/dist/app.js:12
- stringify: frontend/dist/app.js:7, frontend/dist/app.js:9
- workspace: frontend/dist/app.js:6, frontend/dist/app.js:8
- wsPath: frontend/dist/app.js:8, frontend/dist/app.js:9
- Panels: frontend/dist/app.js:8, frontend/dist/app.js:10, frontend/dist/app.js:12

INTENT:
When the play button runs a command, it should first change into the workspace directory so the command executes in the correct working directory. The workspace path is obtained from `window.Panels.workspace()` and safely quoted using `JSON.stringify` before being prefixed as a `cd` command joined with `&&`. If no workspace path is available, the original command should be run unmodified.

DIFF:
diff --git a/frontend/dist/app.js b/frontend/dist/app.js
index 7a80799..c50612d 100644
--- a/frontend/dist/app.js
+++ b/frontend/dist/app.js
@@ -3,6 +3,11 @@ document.addEventListener("click", (ev) => {
   const code = ev.target.closest("[data-run-command]");
   if (!code) return;
   const command = commandFromFence(code.textContent);
+  // Prefix a cd into the workspace so the command always runs in the
+  // correct directory. JSON.stringify quotes the path "safely".
+  const wsPath = (window.Panels && typeof window.Panels.workspace === "function") ? window.Panels.workspace() : "";
+  const full = wsPath ? 'cd ' + JSON.stringify(wsPath) + ' && ' + command : command;
   Panels.setOpen(true);
-  Panels.select("terminal", { command });
+  // The terminal panel writes the string verbatim to its persistent POSIX sh.
+  Panels.select("terminal", { command: full });
 });

