// Reproduce how app.js builds the command string, then exercise the exact
// inputs the allegation names: paths containing $, backtick, space, and quote.
const command = 'echo ran';
const cases = [
  '/tmp/ws$dir',
  '/tmp/ws`back`',
  '/tmp/ws back',
  '/tmp/ws"q"',
];
for (const wsPath of cases) {
  const full = wsPath ? 'cd ' + JSON.stringify(wsPath) + ' && ' + command : command;
  process.stdout.write(full + '\n');
  process.stdout.write('---\n');
}

